<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$channels=db()->query("SELECT * FROM communication_channels WHERE channel_type IN ('whatsapp','sms','voice','generic') ORDER BY id")->fetchAll();$calls=db()->query("SELECT ca.*,p.name project_name,t.title task_title,ch.label channel_label FROM calls ca LEFT JOIN projects p ON p.id=ca.project_id LEFT JOIN tasks t ON t.id=ca.task_id LEFT JOIN communication_channels ch ON ch.id=ca.channel_id ORDER BY ca.id DESC LIMIT 300")->fetchAll();$events=db()->query("SELECT ce.*,ch.label channel_label FROM communication_events ce LEFT JOIN communication_channels ch ON ch.id=ce.channel_id ORDER BY ce.id DESC LIMIT 100")->fetchAll();$waCalls=WhatsAppCallingService::recent(100);AdminUi::header('المكالمات والقنوات','calls');echo AdminUi::flash();?>
<div class="grid"><section class="card span-8"><div class="card-title"><div><h2>بوابة التواصل</h2><span class="muted small">واتساب والرسائل والمكالمات وأي مزود إضافي، وكلهم على نفس المحادثة والذاكرة.</span></div></div><?php foreach($channels as $c):?><div class="agent-row"><div class="grow"><b><?=e($c['label'])?> — <?=e(AdminUi::provider((string)$c['provider']))?></b><small>إرسال: <?=$c['send_enabled']?'نعم':'لا'?> · استقبال: <?=$c['receive_enabled']?'نعم':'لا'?> · آخر اختبار <?=e(AdminUi::date($c['last_test_at']))?></small></div><?=AdminUi::badge($c['enabled']?'active':'disabled')?></div><?php endforeach?></section><section class="card span-4"><div class="card-title"><h2>أوامر صوتية</h2></div><form method="post" action="action.php"><?=AdminUi::csrf()?><input type="hidden" name="action" value="call_owner"><button class="btn">ابدأ مكالمة مع المالك</button></form><a class="btn secondary" style="margin-top:10px" href="integrations.php">إعداد المزودين</a><form method="post" action="action.php" style="margin-top:10px"><?=AdminUi::csrf()?><input type="hidden" name="action" value="whatsapp_call_owner"><input type="hidden" name="return" value="/api/admin/calls.php"><button class="btn secondary">WhatsApp Calling request</button></form><p class="small muted">WhatsApp Calling is capability-gated. It only starts when the configured provider/bridge and account policy allow it; otherwise it records a blocked session instead of pretending a call was placed.</p></section>
<section class="card span-12"><div class="card-title"><h2>سجل المكالمات</h2></div><div class="table-wrap"><table><thead><tr><th>#</th><th>القناة</th><th>الاتجاه</th><th>من</th><th>إلى</th><th>الغرض</th><th>المشروع/المهمة</th><th>الحالة</th><th>الوقت</th></tr></thead><tbody><?php foreach($calls as $c):?><tr><td>#<?=$c['id']?></td><td><?=e($c['channel_label']?:'—')?></td><td><?=e(AdminUi::label((string)$c['direction']))?></td><td><?=e($c['from_ref']?:'—')?></td><td><?=e($c['to_ref']?:'—')?></td><td><?=e($c['purpose']?:'—')?></td><td><?=e(($c['project_name']?:'—').($c['task_title']?' / '.$c['task_title']:''))?></td><td><?=AdminUi::badge($c['state'])?></td><td><?=e(AdminUi::date($c['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card span-12"><div class="card-title"><h2>أحداث القنوات</h2></div><div class="table-wrap"><table><thead><tr><th>#</th><th>القناة</th><th>الحدث</th><th>الحالة</th><th>الوقت</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td>#<?=$e['id']?></td><td><?=e($e['channel_label']?:'—')?></td><td><?=e(AdminUi::label((string)$e['event_type']))?></td><td><?=e(AdminUi::label((string)($e['state']?:'')))?></td><td><?=e(AdminUi::date($e['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section><section class="card span-12"><div class="card-title"><h2>WhatsApp Calling sessions</h2><span class="muted small">Inbound/outbound signaling and bridge state are recorded separately from ordinary voice calls.</span></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Direction</th><th>From</th><th>To</th><th>Agent</th><th>State</th><th>Bridge</th><th>Started</th><th>Ended</th></tr></thead><tbody><?php foreach($waCalls as $w):?><tr><td>#<?=$w['id']?></td><td><?=e($w['direction'])?></td><td><?=e($w['from_ref']?:'-')?></td><td><?=e($w['to_ref']?:'-')?></td><td><?=e($w['agent_name']?:'-')?></td><td><?=AdminUi::badge($w['state'])?></td><td><?=e($w['bridge_session_id']?:'-')?></td><td><?=e(AdminUi::date($w['started_at']))?></td><td><?=e(AdminUi::date($w['ended_at']))?></td></tr><?php endforeach?></tbody></table></div></section></div><?php AdminUi::footer();
